/* Startup computation (constants, monitor option string, geometry sanity
   checks).  Called once, before any component INITIALIZE, from the first
   component's parameter expression. */
static void tof_init(double E0_, double dt_, char *coh_,
                     double thickness_, double yheight_, double radius_,
                     char *container_, double container_thickness_,
                     char *environment_, double environment_radius_,
                     double environment_thickness_, double *dt0_)
{
  double ki, t0, lambda;
  vi     = SE2V*sqrt(E0_);
  ki     = V2K*vi;
  t0     = 1.25/vi;
  lambda = 2*PI/ki;
  sprintf(op, "energy limits=[%g %g] bins=50, theta limits=[5 175] bins=150, banana, parallel", 0.5*E0_, 2*E0_);
  printf("templateTOF: lambda=%g [Angs], k=%g [Angs-1], v=%g [m/s], E=%g [meV]. Time=[%g %g %g]\n",
    lambda, ki, vi, E0_, t0*.75, t0, t0*1.5);
  printf("templateTOF: sample is %s, with %s%s geometry.\n",
    coh_, thickness_ ? "hollow " : "", yheight_ ? "cylindrical" : "spherical");
  if (yheight_ && container_thickness_)
    printf("templateTOF: container is %s (outer cylinder)\n", container_);
  if (environment_thickness_ > 0)
    printf("templateTOF: external environment is %s\n", environment_);
  *dt0_ = dt_;
  if (environment_thickness_ > 0 && radius_ > environment_radius_-environment_thickness_)
    exit(printf("templateTOF: sample radius %g is larger than sample environment %g\n",
      radius_, environment_radius_-environment_thickness_));
  if (container_thickness_ > 0 && environment_thickness_ > 0 && yheight_ > 0
      && radius_+container_thickness_+0.0001 > environment_radius_-environment_thickness_)
    exit(printf("templateTOF: sample container radius %g is larger than sample environment %g\n",
      radius_+container_thickness_+0.0001, environment_radius_-environment_thickness_));
  _dt0 = *dt0_;
  #pragma acc update device(_dt0)
}

